using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using MelloCharts;

public static class CoreTests
{
    static int passed, failed;
    static void Test(string name, Action body) { try { body(); passed++; Console.WriteLine("PASS " + name); } catch (Exception e) { failed++; Console.WriteLine("FAIL " + name + ": " + e.Message); } }
    static void Is(bool value, string message) { if (!value) throw new Exception(message); }
    static void Near(double actual, double expected, double epsilon) { Is(Math.Abs(actual - expected) <= epsilon, "Expected " + expected.ToString("R", CultureInfo.InvariantCulture) + ", got " + actual.ToString("R", CultureInfo.InvariantCulture)); }
    static void Reject(Action body) { bool rejected = false; try { body(); } catch (ArgumentException) { rejected = true; } catch (InvalidDataException) { rejected = true; } Is(rejected, "Invalid input was accepted"); }
    static ChartDocument Doc(string type) { return new ChartDocument { version=1, type=type, title="Dados fictícios", subtitle="", source="Exemplo", unit="R$ mil", palette="ocean", decimals=2, showLabels=true, showBaseline=true, includeTotal=true, rows=new List<ChartRow> { new ChartRow { label="A", actual=10, forecast=5, baseline=12, value=10, kind="base" } } }; }
    static List<SceneElement> Bars(Scene scene) { return scene.Elements.Where(e => e.Type == "rect" && e.Role == "bar").ToList(); }
    static double Luminance(string hex){Color c=ColorTranslator.FromHtml(hex);Func<byte,double> linear=delegate(byte channel){double v=channel/255.0;return v<=0.04045?v/12.92:Math.Pow((v+0.055)/1.055,2.4);};return .2126*linear(c.R)+.7152*linear(c.G)+.0722*linear(c.B);}
    static string Xlsx(string sheet, bool rich, bool external)
    {
        string file = Path.Combine(Path.GetTempPath(), "mello-test-" + Guid.NewGuid().ToString("N") + ".xlsx");
        using (FileStream fs = File.Create(file)) using (ZipArchive zip = new ZipArchive(fs, ZipArchiveMode.Create))
        {
            Entry(zip, "xl/workbook.xml", "<workbook xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Dados' sheetId='8' r:id='rOther'/><sheet name='Ignorar' sheetId='9' r:id='rIgnore'/></sheets></workbook>");
            Entry(zip, "xl/_rels/workbook.xml.rels", "<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rOther' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet' Target='worksheets/custom.xml'" + (external ? " TargetMode='External'" : "") + "/><Relationship Id='rIgnore' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet' Target='worksheets/ignored.xml'/>" + (rich ? "<Relationship Id='strings' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings' Target='strings.xml'/>" : "") + "</Relationships>");
            Entry(zip, "xl/worksheets/custom.xml", "<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData>" + sheet + "</sheetData></worksheet>");
            if (rich) Entry(zip,"xl/strings.xml", "<sst xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><si><r><t>Pro</t></r><r><t>jeto</t></r></si></sst>");
        }
        return file;
    }
    static void Entry(ZipArchive zip, string path, string text) { using (StreamWriter w = new StreamWriter(zip.CreateEntry(path).Open(), new UTF8Encoding(false))) w.Write(text); }
    static void ReplacePart(string file,string path,string content) { using(FileStream fs=new FileStream(file,FileMode.Open,FileAccess.ReadWrite)) using(ZipArchive zip=new ZipArchive(fs,ZipArchiveMode.Update)) { ZipArchiveEntry old=zip.GetEntry(path);if(old!=null)old.Delete();Entry(zip,path,content); } }
    static void RejectContaining(Action body,string part) { try { body(); } catch(ArgumentException e) { Is(e.Message.Contains(part),"Unexpected rejection: "+e.Message);return; } catch(InvalidDataException e) { Is(e.Message.Contains(part),"Unexpected rejection: "+e.Message);return; } throw new Exception("Invalid input was accepted"); }
    static string Cell(string reference, string value) { return "<c r='" + reference + "' t='inlineStr'><is><t>" + value + "</t></is></c>"; }
    static string Header() { return "<row r='1'>" + Cell("A1","categoria") + Cell("B1","realizado") + Cell("C1","projetado") + Cell("D1","baseline") + "</row>"; }
    static string Data(string actual, string forecast, string baseline) { return "<row r='2'><c r='A2' t='s'><v>0</v></c>" + actual + forecast + baseline + "</row>"; }
    static void WithXlsx(string sheet, bool rich, bool external, Action<string> action) { string path=Xlsx(sheet,rich,external); try { action(path); } finally { File.Delete(path); } }

    public static int Main()
    {
        Test("legacy projects receive presentation defaults", delegate { string json=ChartCore.Serialize(Doc("columns"));json=System.Text.RegularExpressions.Regex.Replace(json,"\"style\":\"[^\"]*\",","");json=System.Text.RegularExpressions.Regex.Replace(json,"\"compactNumbers\":(?:true|false),","");json=System.Text.RegularExpressions.Regex.Replace(json,"\"showGrid\":(?:true|false),","");string upgraded=ChartCore.Serialize(ChartCore.Deserialize(json));Is(upgraded.Contains("\"style\":\"executive\"") && upgraded.Contains("\"showGrid\":true") && upgraded.Contains("\"compactNumbers\":false"),"Legacy presentation defaults missing"); });
        Test("presentation options survive JSON and reject invalid types", delegate { string original=ChartCore.Serialize(Doc("columns"));string json=System.Text.RegularExpressions.Regex.Replace(original,"\"style\":\"[^\"]*\",|\"compactNumbers\":(?:true|false),|\"showGrid\":(?:true|false),","");json=json.Replace("\"version\":1","\"version\":1,\"style\":\"dark\",\"compactNumbers\":true,\"showGrid\":false");string roundtrip=ChartCore.Serialize(ChartCore.Clone(ChartCore.Deserialize(json)));Is(roundtrip.Contains("\"style\":\"dark\"") && roundtrip.Contains("\"compactNumbers\":true") && roundtrip.Contains("\"showGrid\":false"),"Style lost on roundtrip");foreach(string bad in new[]{json.Replace("\"dark\"","\"unknown\""),json.Replace("\"showGrid\":false","\"showGrid\":null"),json.Replace("\"compactNumbers\":true","\"compactNumbers\":1")})Reject(delegate{ChartCore.Deserialize(bad);}); });
        Test("dark style includes an opaque background and light headings", delegate { string json=ChartCore.Serialize(Doc("columns"));json=System.Text.RegularExpressions.Regex.Replace(json,"\"style\":\"[^\"]*\",","").Replace("\"version\":1","\"version\":1,\"style\":\"dark\"");Scene scene=ChartCore.BuildScene(ChartCore.Deserialize(json));SceneElement bg=scene.Elements.First();Is(bg.Type=="rect" && bg.Role=="background" && bg.W==scene.Width && bg.H==scene.Height && bg.Color!="#FFFFFF","Dark background missing");Is(scene.Elements.First(e=>e.Role=="title").Color=="#F3F6FB","Heading lacks dark-style contrast"); });
        Test("hidden grid keeps the zero reference", delegate { string json=ChartCore.Serialize(Doc("columns"));json=System.Text.RegularExpressions.Regex.Replace(json,"\"showGrid\":(?:true|false),","").Replace("\"version\":1","\"version\":1,\"showGrid\":false");Scene scene=ChartCore.BuildScene(ChartCore.Deserialize(json));Is(!scene.Elements.Any(e=>e.Role=="grid"),"Grid still visible");Is(scene.Elements.Count(e=>e.Role=="zeroAxis")==1,"Zero reference missing"); });
        Test("compact labels retain original precision and explain their unit", delegate { ChartDocument d=Doc("buildup");d.rows[0].actual=1250000.125;d.rows[0].forecast=250000.375;d.rows[0].baseline=1450000;d.decimals=1;string json=System.Text.RegularExpressions.Regex.Replace(ChartCore.Serialize(d),"\"compactNumbers\":(?:true|false),","").Replace("\"version\":1","\"version\":1,\"compactNumbers\":true");ChartDocument compact=ChartCore.Deserialize(json);Scene scene=ChartCore.BuildScene(compact);Is(scene.Elements.Any(e=>e.Role=="value" && e.Text=="1,5 mi"),"Large total is not compact");Is(scene.Elements.Any(e=>e.Role=="unit" && e.Text.Contains("abreviado")),"Compact unit not identified");Near(compact.rows[0].actual,1250000.125,0);Near(ChartCore.ImportDelimited(ChartCore.ToCsv(compact),"buildup").rows[0].forecast,250000.375,0); });
        Test("paired column labels have disjoint horizontal frames", delegate { ChartDocument d=ChartCore.Example("columns");foreach(ChartRow r in d.rows){r.actual=250;r.forecast=250;}Scene scene=ChartCore.BuildScene(d);for(int i=0;i<d.rows.Count;i++){SceneElement[] labels=scene.Elements.Where(e=>e.Role=="value" && e.Category==i).OrderBy(e=>e.X).ToArray();Is(labels.Length==2 && labels[0].X+labels[0].W<=labels[1].X,"Column labels overlap");} });
        Test("column labels center over their actual bar at every density", delegate { foreach(int count in new[]{1,4,12}){ChartDocument d=Doc("columns");while(d.rows.Count<count)d.rows.Add(new ChartRow{label="B",actual=10,forecast=5});Scene scene=ChartCore.BuildScene(d);foreach(int category in Enumerable.Range(0,count)){var bars=Bars(scene).Where(e=>e.Category==category).ToArray();var values=scene.Elements.Where(e=>e.Role=="value" && e.Category==category).ToArray();for(int j=0;j<2;j++)Near(values[j].X+values[j].W/2,bars[j].X+bars[j].W/2,0.00001);}} });
        Test("axis uses conventional absolute steps", delegate { ChartDocument d=ChartCore.Example("buildup");Scene scene=ChartCore.BuildScene(d);double[] ticks=scene.Elements.Where(e=>e.Role=="tick").Select(e=>ChartCore.ParseNumber(e.Text)).OrderBy(v=>v).ToArray();double difference=ticks[1]-ticks[0],power=Math.Pow(10,Math.Floor(Math.Log10(difference)));Is(new[]{1.0,2,2.5,5,10}.Any(v=>Math.Abs(v-difference/power)<0.000001),"Awkward tick interval: "+difference); });
        Test("fractional axis steps retain their decimal precision", delegate { ChartDocument d=Doc("buildup");d.includeTotal=false;d.showBaseline=false;d.rows[0].actual=9;d.rows[0].forecast=0;d.decimals=0;Scene scene=ChartCore.BuildScene(d);Is(scene.Elements.Any(e=>e.Role=="tick" && e.Text=="2,5"),"Fractional tick rounded to integer"); });
        Test("waterfall value text meets contrast in every palette and style", delegate { foreach(string style in new[]{"executive","minimal","dark"})foreach(string palette in new[]{"ocean","forest","ink"}){ChartDocument d=ChartCore.Example("waterfall");d.style=style;d.palette=palette;Scene scene=ChartCore.BuildScene(d);double bg=Luminance(scene.Elements.First().Color);foreach(SceneElement e in scene.Elements.Where(e=>e.Role=="value")){double fg=Luminance(e.Color);Is((Math.Max(bg,fg)+.05)/(Math.Min(bg,fg)+.05)>=4.5,"Low contrast: "+style+" / "+palette+" / "+e.Color);}} });
        Test("all styles fit the canvas at maximum category count", delegate { foreach(string style in new[]{"executive","minimal","dark"})foreach(string type in new[]{"buildup","waterfall","columns"}){ChartDocument d=Doc(type);d.style=style;d.compactNumbers=true;d.rows.Clear();for(int i=0;i<12;i++)d.rows.Add(new ChartRow{label="Frente "+(i+1),actual=1000000+i*10000,forecast=250000,baseline=1100000,value=i==0?1000000:10000,kind=i==0?"base":"delta"});foreach(SceneElement e in ChartCore.BuildScene(d).Elements)Is(e.X>=0 && e.Y>=0 && e.X+e.W<=1280.001 && e.Y+e.H<=720.001,"Element outside canvas in "+style+" / "+type+" / "+e.Role);} });
        Test("negative waterfall labels stay above category area", delegate { ChartDocument d=Doc("waterfall");d.rows[0].value=10;d.rows.Add(new ChartRow{label="Redução total",kind="delta",value=-10});Scene scene=ChartCore.BuildScene(d);double categories=scene.Elements.Where(e=>e.Role=="category").Min(e=>e.Y);Is(scene.Elements.Where(e=>e.Role=="value").All(e=>e.Y+e.H<categories),"Waterfall label collides with categories"); });
        Test("PNG renderer preserves dark background and requested dimensions", delegate { var render=typeof(ChartPreview).GetMethod("RenderImage",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static);Is(render!=null,"PNG renderer missing");string json=System.Text.RegularExpressions.Regex.Replace(ChartCore.Serialize(Doc("columns")),"\"style\":\"[^\"]*\",","").Replace("\"version\":1","\"version\":1,\"style\":\"dark\"");using(Bitmap bitmap=(Bitmap)render.Invoke(null,new object[]{ChartCore.BuildScene(ChartCore.Deserialize(json)),1920,1080})){Is(bitmap.Width==1920 && bitmap.Height==1080,"Wrong export size");Is(bitmap.GetPixel(1,1).ToArgb()==ColorTranslator.FromHtml("#101E2E").ToArgb(),"Export background mismatch");using(MemoryStream stream=new MemoryStream()){bitmap.Save(stream,System.Drawing.Imaging.ImageFormat.Png);Is(stream.Length>10000,"Export is unexpectedly blank");}} });
        Test("examples validate and keep fictional source", delegate { foreach(string type in new string[]{"buildup","waterfall","columns"}) { ChartDocument d=ChartCore.Example(type); ChartCore.Validate(d); Is(d.rows.Count>1 && d.source.Contains("fictícios"),"Example incomplete"); } });
        Test("unknown example type rejected", delegate { Reject(delegate { ChartCore.Example("unsupported-type"); }); });
        Test("validation rejects missing title and too many rows", delegate { ChartDocument d=Doc("buildup"); d.title=" "; Reject(delegate { ChartCore.Validate(d); }); d.title="A"; while(d.rows.Count<13) d.rows.Add(new ChartRow {label="A"}); Reject(delegate { ChartCore.Validate(d); }); });
        Test("validation rejects nonfinite oversized and negative buildup", delegate { foreach(double n in new double[]{Double.NaN,Double.PositiveInfinity,1000000001,-1}) { ChartDocument d=Doc("buildup"); d.rows[0].actual=n; Reject(delegate { ChartCore.Validate(d); }); } });
        Test("columns accept negatives and boundary values", delegate { ChartDocument d=Doc("columns"); d.rows[0].actual=-1000000000; d.rows[0].forecast=1000000000; ChartCore.Validate(d); });
        Test("waterfall requires one initial base", delegate { ChartDocument d=Doc("waterfall"); d.rows[0].kind="delta"; Reject(delegate { ChartCore.Validate(d); }); d.rows[0].kind="base"; d.rows.Add(new ChartRow{label="Second",kind="base"}); Reject(delegate { ChartCore.Validate(d); }); });
        Test("clone is independent and serialization preserves precision", delegate { ChartDocument d=Doc("columns"); d.rows[0].actual=0.123456789012345; ChartDocument clone=ChartCore.Clone(d); Near(clone.rows[0].actual,0.123456789012345,0); clone.rows[0].label="Changed"; Is(d.rows[0].label=="A","Clone aliases row"); Is(ChartCore.Serialize(d).Contains("\"actual\""),"Wrong JSON fields"); });
        Test("JSON requires numeric and presentation fields", delegate { string json=ChartCore.Serialize(Doc("columns")); Reject(delegate { ChartCore.Deserialize(json.Replace("\"actual\":10,","")); }); Reject(delegate { ChartCore.Deserialize(json.Replace("\"showLabels\":true,","")); }); Reject(delegate { ChartCore.Deserialize(json.Replace("\"forecast\":5","\"forecast\":\"5\"")); }); });
        Test("JSON rejects nulls invalid roots and oversized input", delegate { Reject(delegate { ChartCore.Deserialize("{}"); }); Reject(delegate { ChartCore.Deserialize("[]"); }); Reject(delegate { ChartCore.Deserialize("null"); }); Reject(delegate { ChartCore.Deserialize(new string(' ',1000001)); }); });
        Test("project JSON requires strict syntax and unique keys", delegate { string json=ChartCore.Serialize(Doc("columns")); foreach(string invalid in new string[]{json.Replace("\"version\":","version:"),json.Replace("\"columns\"","'columns'"),json.Substring(0,json.Length-1)+",}",json.Replace("\"version\":1","\"version\":1,\"version\":1"),json.Replace("\"actual\":10","\"actual\":01")})Reject(delegate{ChartCore.Deserialize(invalid);}); });
        Test("numbers parse PTBR US parentheses and exponents", delegate { Near(ChartCore.ParseNumber("R$ 1.234,56"),1234.56,0); Near(ChartCore.ParseNumber("1,234.56"),1234.56,0); Near(ChartCore.ParseNumber("(12,5)"),-12.5,0); Near(ChartCore.ParseNumber("1.234"),1234,0); Near(ChartCore.ParseNumber("1E-07"),0.0000001,0); });
        Test("numbers reject junk and empty values", delegate { foreach(string s in new string[]{"", " ", "1x", "1,2,3", "Infinity", "1e12", "--2"}) Reject(delegate { ChartCore.ParseNumber(s); }); });
        Test("CSV supports BOM quotes separators and decimal commas", delegate { ChartDocument d=ChartCore.ImportDelimited("\uFEFFcategoria;realizado;projetado;baseline\r\n\"A; \"\"B\"\"\";1.234,56;10,25;1200\r\n","buildup"); Is(d.rows[0].label=="A; \"B\"","Quoted field corrupt"); Near(d.rows[0].actual,1234.56,0); Near(d.rows[0].forecast,10.25,0); });
        Test("CSV detects comma separator outside quoted header", delegate { ChartDocument d=ChartCore.ImportDelimited("\"categoria\",realizado,projetado,baseline\n\"A;B;C;D\",1.5,2.5,3.5","columns"); Near(d.rows[0].actual,1.5,0); });
        Test("CSV accepts tabs and translated waterfall kinds", delegate { ChartDocument d=ChartCore.ImportDelimited("etapa\tvalor\ttipo\nInicial\t100\tbase\nVariação\t-5\tvariação\nParcial\t0\tsubtotal","waterfall"); Is(d.rows[2].kind=="total","Subtotal not recognized"); });
        Test("CSV rejects quotes duplicate aliases blank values and ragged rows", delegate { foreach(string s in new string[]{"categoria;realizado;projetado;baseline\n\"A;1;2;3", "categoria;realizado;actual;projetado;baseline\nA;1;1;2;3", "categoria;realizado;projetado;baseline\nA;;2;3", "categoria;realizado;projetado;baseline\nA;1;2"}) Reject(delegate { ChartCore.ImportDelimited(s,"buildup"); }); });
        Test("CSV export preserves precision and protects formula labels", delegate { ChartDocument d=Doc("columns"); d.rows[0].label="=SUM(A1)"; d.rows[0].actual=0.123456789012345; string csv=ChartCore.ToCsv(d); Is(csv.StartsWith("\uFEFF"),"BOM missing"); Is(csv.Contains("'="),"Formula injection not escaped"); Near(ChartCore.ImportDelimited(csv,"columns").rows[0].actual,0.123456789012345,0); });
        Test("waterfall subtotal exports automatic zero placeholder", delegate { ChartDocument d=Doc("waterfall"); d.rows.Add(new ChartRow{label="Delta",kind="delta",value=-3.25}); d.rows.Add(new ChartRow{label="Total",kind="total",value=999}); string csv=ChartCore.ToCsv(d); Is(csv.Contains("\"Total\";0;total"),"Subtotal did not use automatic placeholder"); });
        Test("waterfall CSV roundtrip keeps computed totals above per-cell limit", delegate { ChartDocument d=Doc("waterfall");d.rows[0].value=1000000000;d.rows.Add(new ChartRow{label="Incremento",kind="delta",value=1000000000});d.rows.Add(new ChartRow{label="Final",kind="total",value=0});ChartDocument imported=ChartCore.ImportDelimited(ChartCore.ToCsv(d),"waterfall");List<SceneElement> bars=Bars(ChartCore.BuildScene(imported));Near(bars[2].H/bars[0].H,2,0.00000001);Is(imported.rows[2].value==0,"Subtotal must remain automatic"); });
        Test("buildup stacks remaining forecast and appends exact total", delegate { ChartDocument d=Doc("buildup"); d.rows[0].actual=0.123456; d.rows[0].forecast=0.234567; d.rows[0].baseline=0; Scene s=ChartCore.BuildScene(d); List<SceneElement> bars=Bars(s); Is(bars.Count==4,"Expected two stacked categories including total"); Near(bars[0].X,bars[1].X,0); Near(bars[0].W,bars[1].W,0); Near(bars[1].Y+bars[1].H,bars[0].Y,0.00000001); Near(bars[0].H/bars[1].H,0.123456/0.234567,0.00000001); Near(bars[0].H,bars[2].H,0.00000001); });
        Test("buildup can hide total and baseline", delegate { ChartDocument d=Doc("buildup"); d.includeTotal=false; d.showBaseline=false; Scene s=ChartCore.BuildScene(d); Is(Bars(s).Count==2,"Hidden total shown"); Is(!s.Elements.Any(e=>e.Role=="baseline"),"Hidden baseline shown"); });
        Test("waterfall handles deltas subtotal and continuation without rounding", delegate { ChartDocument d=Doc("waterfall"); d.rows[0].value=0.1; d.rows.Add(new ChartRow{label="Up",kind="delta",value=0.2}); d.rows.Add(new ChartRow{label="Subtotal",kind="total",value=900}); d.rows.Add(new ChartRow{label="Down",kind="delta",value=-0.15}); d.rows.Add(new ChartRow{label="Final",kind="total"}); Scene s=ChartCore.BuildScene(d); List<SceneElement> b=Bars(s); Is(b.Count==5,"Wrong waterfall bars"); Near(b[2].H/b[0].H,3,0.00000001); Near(b[4].H/b[0].H,1.5,0.00000001); Is(s.Elements.Any(e=>e.Type=="text" && e.Text=="0,15"),"Final label wrong"); });
        Test("columns group series and expose optional connected baseline", delegate { ChartDocument d=Doc("columns"); d.rows[0].actual=-10; d.rows.Add(new ChartRow{label="B",actual=20,forecast=15,baseline=17}); Scene s=ChartCore.BuildScene(d); List<SceneElement> b=Bars(s); Is(b.Count==4 && b[0].X!=b[1].X,"Series not grouped"); Is(s.Elements.Count(e=>e.Type=="line" && e.Role=="baseline")==1,"Baseline connection missing"); d.showBaseline=false; Is(!ChartCore.BuildScene(d).Elements.Any(e=>e.Role=="baseline"),"Baseline remains"); });
        Test("all zero and very small scenes stay finite", delegate { foreach(double n in new double[]{0,0.000000000001,1000000000}) { ChartDocument d=Doc("buildup"); d.rows[0].actual=n; d.rows[0].forecast=n; d.rows[0].baseline=n; Scene s=ChartCore.BuildScene(d); Is(s.Width==1280 && s.Height==720,"Wrong scene size"); foreach(SceneElement e in s.Elements) { foreach(double v in new double[]{e.X,e.Y,e.W,e.H,e.X2,e.Y2,e.Size}) Is(!Double.IsNaN(v)&&!Double.IsInfinity(v),"Nonfinite geometry"); Is(e.W>=0&&e.H>=0,"Negative geometry"); } } });
        Test("XLSX resolves first sheet relations and rich shared strings", delegate { WithXlsx(Header()+Data("<c r='B2'><v>2.25</v></c>","<c r='C2'><f>B2*2</f><v>4.5</v></c>","<c r='D2'><v>7</v></c>"),true,false,delegate(string path){ ChartDocument d=ChartCore.ImportXlsx(path,"buildup"); Is(d.rows[0].label=="Projeto","Rich shared string lost"); Near(d.rows[0].forecast,4.5,0); }); });
        Test("XLSX inline strings and omitted row coordinates are supported", delegate { string sheet="<row>"+Cell("A1","categoria")+Cell("B1","realizado")+Cell("C1","projetado")+Cell("D1","baseline")+"</row><row>"+Cell("A2","Teste")+"<c r='B2'><v>1.25</v></c><c r='C2'><v>2</v></c><c r='D2'><v>3</v></c></row>"; WithXlsx(sheet,false,false,delegate(string path){ Near(ChartCore.ImportXlsx(path,"columns").rows[0].actual,1.25,0); }); });
        Test("XLSX rejects cached errors and uncached formulas", delegate { foreach(string actual in new string[]{"<c r='B2' t='e'><v>#DIV/0!</v></c>","<c r='B2'><f>SUM(1,2)</f></c>"}) WithXlsx(Header()+Data(actual,"<c r='C2'><v>2</v></c>","<c r='D2'><v>3</v></c>"),true,false,delegate(string path){ Reject(delegate{ChartCore.ImportXlsx(path,"buildup");}); }); });
        Test("XLSX rejects external sheets and missing numeric cells", delegate { WithXlsx(Header()+Data("<c r='B2'><v>1</v></c>","<c r='C2'><v>2</v></c>","<c r='D2'><v>3</v></c>"),true,true,delegate(string path){ Reject(delegate{ChartCore.ImportXlsx(path,"buildup");}); }); WithXlsx(Header()+Data("","<c r='C2'><v>2</v></c>","<c r='D2'><v>3</v></c>"),true,false,delegate(string path){Reject(delegate{ChartCore.ImportXlsx(path,"buildup");});}); });
        Test("XLSX rejects cells outside bounded range", delegate { WithXlsx(Header()+"<row r='999999'><c r='A999999'><v>1</v></c></row>",false,false,delegate(string path){ Reject(delegate{ChartCore.ImportXlsx(path,"buildup");}); }); });
        Test("XLSX rejects DTD and decompression bombs", delegate { string path=Path.Combine(Path.GetTempPath(),"mello-bomb-"+Guid.NewGuid().ToString("N")+".xlsx"); try { using(FileStream fs=File.Create(path)) using(ZipArchive z=new ZipArchive(fs,ZipArchiveMode.Create)) Entry(z,"xl/workbook.xml",new string(' ',9000000)); Reject(delegate{ChartCore.ImportXlsx(path,"buildup");}); } finally { File.Delete(path); } });
        Test("XLSX numeric cells use invariant decimals without PTBR grouping", delegate { WithXlsx(Header()+Data("<c r='B2'><v>1.234</v></c>","<c r='C2'><v>2E-5</v></c>","<c r='D2'><v>3</v></c>"),true,false,delegate(string path){ChartDocument d=ChartCore.ImportXlsx(path,"buildup");Near(d.rows[0].actual,1.234,0);Near(d.rows[0].forecast,0.00002,0);}); });
        Test("XLSX XML parser rejects DTD without resolving entities", delegate { WithXlsx(Header(),false,false,delegate(string path){ReplacePart(path,"xl/workbook.xml","<!DOCTYPE workbook [<!ENTITY bad SYSTEM 'file:///mello-must-never-read'>]><workbook xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'>&bad;</workbook>");RejectContaining(delegate{ChartCore.ImportXlsx(path,"columns");},"XML XLSX inválido");}); });
        Test("XLSX supports root officeDocument relationship and strict namespaces", delegate { WithXlsx(Header()+"<row r='2'>"+Cell("A2","Inline")+"<c r='B2'><v>1</v></c><c r='C2'><v>2</v></c><c r='D2'><v>3</v></c></row>",false,false,delegate(string path){ReplacePart(path,"_rels/.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='book' Type='http://purl.oclc.org/ooxml/officeDocument/relationships/officeDocument' Target='/xl/workbook.xml'/></Relationships>");ReplacePart(path,"xl/workbook.xml","<workbook xmlns='http://purl.oclc.org/ooxml/spreadsheetml/main' xmlns:r='http://purl.oclc.org/ooxml/officeDocument/relationships'><sheets><sheet name='Dados' sheetId='8' r:id='rOther'/></sheets></workbook>");Near(ChartCore.ImportXlsx(path,"columns").rows[0].actual,1,0);}); });
        Test("XLSX reports numeric gaps and uncached formulas at their boundary", delegate { WithXlsx(Header()+Data("","<c r='C2'><v>2</v></c>","<c r='D2'><v>3</v></c>"),true,false,delegate(string path){RejectContaining(delegate{ChartCore.ImportXlsx(path,"buildup");},"Número inválido");});WithXlsx(Header()+Data("<c r='B2'><f>1+1</f></c>","<c r='C2'><v>2</v></c>","<c r='D2'><v>3</v></c>"),true,false,delegate(string path){RejectContaining(delegate{ChartCore.ImportXlsx(path,"buildup");},"fórmula sem valor em cache");}); });
        Test("maximum categories and summed values generate finite scenes", delegate { foreach(string type in new string[]{"buildup","columns","waterfall"}) { ChartDocument d=Doc(type);d.rows.Clear();for(int i=0;i<12;i++)d.rows.Add(new ChartRow{label="Categoria "+i,actual=1000000000,forecast=1000000000,baseline=1000000000,value=1000000000,kind=i==0?"base":"delta"});Scene s=ChartCore.BuildScene(d);Is(s.Elements.Any(e=>e.Type=="text" && e.Text.Replace("\n","").Replace(" ","")=="Categoria11"),"Category omitted");foreach(SceneElement e in s.Elements)Is(!Double.IsInfinity(e.Y)&&!Double.IsNaN(e.Y),"Bad maximum geometry");} });
        Test("subnormal numbers and all negative columns generate finite geometry", delegate { ChartDocument d=Doc("columns");d.rows[0].actual=Double.Epsilon;d.rows[0].forecast=Double.Epsilon;d.rows[0].baseline=Double.Epsilon;foreach(SceneElement e in ChartCore.BuildScene(d).Elements)Is(!Double.IsNaN(e.Y)&&!Double.IsInfinity(e.Y),"Bad subnormal geometry");d.rows[0].actual=-10;d.rows[0].forecast=-20;d.rows[0].baseline=-15;List<SceneElement> b=Bars(ChartCore.BuildScene(d));Is(b.Count==2 && b[1].H>b[0].H,"Negative bars wrong"); });
