        Test("labels can be hidden without hiding categories", delegate { ChartDocument d=Doc("buildup");d.showLabels=false;Scene s=ChartCore.BuildScene(d);Is(!s.Elements.Any(e=>e.Role=="value" || e.Role=="actualValue" || e.Role=="forecastValue"),"Data label visible");Is(s.Elements.Any(e=>e.Role=="category"),"Category hidden"); });
        Test("maximum chart value and category labels fit their rendered frames", delegate {
