                    ChartDocument d=Doc(type);d.title=new string('W',80);d.rows.Clear();for(int i=0;i<12;i++)d.rows.Add(new ChartRow{label="aaaa aaaa aaaa aaaa aaaa aaaa",actual=1000000000,forecast=1000000000,baseline=1000000000,value=1000000000,kind=i==0?"base":"delta"});
                    foreach(SceneElement e in ChartCore.BuildScene(d).Elements.Where(e=>e.Type=="text"))using(Font font=new Font("Arial",(float)e.Size,e.Bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(StringFormat format=new StringFormat()) {
                        SizeF measured=graphics.MeasureString(e.Text,font,new SizeF((float)e.W,10000),format);Is(measured.Height<=e.H+0.5,"Text frame clips "+e.Role+" in "+type+": "+measured.Height+" > "+e.H);
